interface User {
  id: string;
  email: string;
}

function isUser(value: unknown): value is User {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.id === 'string' && typeof v.email === 'string';
}

async function fetchUser(id: string): Promise<User> {
  const res = await fetch(`/api/users/${id}`);
  const raw: unknown = await res.json();
  if (!isUser(raw)) throw new Error('Invalid user payload');
  return raw;
}

interface Session {
  userId: string;
  roles: string[];
}

function isSession(x: unknown): x is Session {
  return (
    typeof x === 'object' && x !== null &&
    typeof (x as Session).userId === 'string' &&
    Array.isArray((x as Session).roles) &&
    (x as Session).roles.every(r => typeof r === 'string')
  );
}

async function getSession(id: string): Promise<Session | null> {
  const cached = await redis.get(`session:${id}`);
  if (!cached) return null;
  const parsed: unknown = JSON.parse(cached);
  if (!isSession(parsed)) {
    await redis.del(`session:${id}`);
    return null;
  }
  return parsed;
}

function assertIsUser(value: unknown): asserts value is User {
  if (!isUser(value)) {
    throw new TypeError('Expected User shape');
  }
}

function handleWebhook(body: unknown) {
  assertIsUser(body);
  sendEmail(body.email); // body is User here
